'use strict';
/* HYBRID 2.3 — Fitness Neon skin; lógica baseada na 2.2. GitHub Pages + armazenamento local.
   Migrates v1 silently and keeps the original v1 key intact for recovery. */
const STORE='hybridTrainingV2', LEGACY='hybridTrainingPersonalV1';
const DAYS=['SEG','TER','QUA','QUI','SEX','SÁB','DOM'];
const WD=['A','EASY','B','C','QUALITY','REST','LONG'];
const RX={A:'Superiores A',B:'Inferiores B',C:'Superiores C',EASY:'Corrida leve',QUALITY:'Corrida de qualidade',LONG:'Longão',REST:'Descanso'};
/* SVG line icons: bundled in source, no emoji, no CDN, no external font. */
const ICONS={
 home:'<path d="m3 10 9-7 9 7v10a1 1 0 0 1-1 1h-5v-7H9v7H4a1 1 0 0 1-1-1z"/>',
 dumbbell:'<path d="m6.5 6.5 11 11M5 4l-1 1m2-2-3 3m16 13 1 1m-2 2 3-3M8 8l-3 3m3-3 8 8m0 0 3-3M3 8l5-5m8 18 5-5"/>',
 calendar:'<rect x="3" y="5" width="18" height="16" rx="2"/><path d="M7 3v4m10-4v4M3 10h18m-14 4h3m4 0h3m-10 4h3"/>',
 chart:'<path d="M3 20h18M5 16l5-5 4 3 6-8M16 6h4v4"/>',
 settings:'<path d="M12 8a4 4 0 1 0 0 8 4 4 0 0 0 0-8z"/><path d="M19 13.5v-3l2-1.5-2-3.4-2.3.8-2.6-1.5L13.5 2h-3l-.6 2.9-2.6 1.5L5 5.6 3 9l2 1.5v3L3 15l2 3.4 2.3-.8 2.6 1.5.6 2.9h3l.6-2.9 2.6-1.5 2.3.8L21 15z"/>',
 moon:'<path d="M20.9 13a9 9 0 0 1-9.9-9.9A9 9 0 1 0 20.9 13z"/>',
 run:'<circle cx="14" cy="4" r="2"/><path d="m8 21 3-5-3-4-4 2m15-3-4-2-3-1-3 4 4 3-2 6m1-13 3 3 4 1"/>',
 clock:'<circle cx="12" cy="12" r="9"/><path d="M12 7v5l3 2"/>',
 check:'<path d="m5 12 4 4L19 6"/>',
 edit:'<path d="M12 20h9M4 16l-.5 4.5L8 20l12-12-4-4L4 16z"/>',
 plus:'<path d="M12 5v14M5 12h14"/>',
 minus:'<path d="M5 12h14"/>',
 download:'<path d="M12 3v12m-5-5 5 5 5-5M4 17v4h16v-4"/>',
 upload:'<path d="M12 17V5m-5 5 5-5 5 5M4 17v4h16v-4"/>',
 right:'<path d="M5 12h14m-6-6 6 6-6 6"/>',
 left:'<path d="M19 12H5m6-6-6 6 6 6"/>',
 'chev-left':'<path d="m15 18-6-6 6-6"/>',
 'chev-right':'<path d="m9 18 6-6-6-6"/>',
 up:'<path d="m6 15 6-6 6 6"/>',
 down:'<path d="m6 9 6 6 6-6"/>',
 pause:'<path d="M8 5v14M16 5v14"/>',
 play:'<path d="m8 5 12 7-12 7z"/>',
 x:'<path d="M5 5 19 19M19 5 5 19"/>',
 refresh:'<path d="M20 7v5h-5M4 17v-5h5"/><path d="M5.5 9a8 8 0 0 1 13.5-2L20 12M4 12l1 5a8 8 0 0 0 13.5-2"/>',
 alert:'<path d="m12 3 10 18H2L12 3zM12 9v5m0 4h.01"/>',
 weight:'<path d="M7 9V7a5 5 0 0 1 10 0v2M5 9h14l2 12H3z"/>',
};
function icon(name, size=19){const content=ICONS[name]||ICONS.check;return `<svg class="ui-icon" width="${size}" height="${size}" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${content}</svg>`}

const SEED_PLANS={
 A:{name:'Superiores A',focus:'Peito, costas, ombros e braços',kind:'gym',exercises:[
 ['supino_reto','Supino reto com barra',4,'6–8',150,2.5],['barra_fixa','Barra fixa ou puxada alta',4,'6–10',150,2.5],['supino_inclinado','Supino inclinado com halteres',3,'8–12',120,2],['remada_articulada','Remada articulada',3,'8–12',120,2.5],['elevacao_lateral_a','Elevação lateral',3,'12–20',75,1],['rosca_direta','Rosca direta',2,'10–12',75,2],['triceps_polia','Tríceps na polia',2,'10–15',75,2.5]]},
 B:{name:'Inferiores B',focus:'Pernas, glúteos e core',kind:'gym',exercises:[
 ['agachamento','Agachamento livre ou leg press',3,'5–8',180,2.5],['extensao_45','Extensão de quadril no banco 45°',3,'8–12',120,2.5],['bulgaro','Afundo búlgaro',2,'8–10 por perna',120,2],['flexora','Mesa flexora',3,'10–15',90,2.5],['panturrilha','Panturrilha em pé',3,'10–15',75,2.5],['abducao','Abdução de quadril',2,'12–20',75,2.5],['pallof','Pallof press',2,'10–12 por lado',75,2.5]]},
 C:{name:'Superiores C',focus:'Ombros, costas, peito e braços',kind:'gym',exercises:[
 ['desenvolvimento','Desenvolvimento com halteres',3,'8–10',120,2],['remada_baixa','Remada baixa',3,'8–12',120,2.5],['crucifixo','Crucifixo na máquina / peck deck',3,'10–15',90,2.5],['puxada_neutra','Puxada alta pegada neutra',3,'8–12',120,2.5],['elevacao_lateral_c','Elevação lateral',3,'12–20',75,1],['rosca_martelo','Rosca martelo',3,'10–12',75,2],['triceps_frances','Tríceps francês',3,'10–12',75,2]]}
};
function clone(x){return JSON.parse(JSON.stringify(x))}
function buildPlans(){const p={};for(const [key,v] of Object.entries(SEED_PLANS))p[key]={name:v.name,focus:v.focus,kind:'gym',exercises:v.exercises.map(([id,name,sets,target,rest,step])=>({id,name,sets,target,rest,step}))};return p}
const blank=()=>({version:2,plans:buildPlans(),sessions:{},events:{},overrides:{},measures:[],settings:{timer:true,sound:false,unit:'kg',defaultIncrement:2.5,weeklyTypes:[...WD]},timer:null,migrated:false,scheduleMigrated:true});
let state=blank(),storageOK=true,tab='home',selected=today(),selectedType=null,monthCursor='',chartExercise='A|supino_reto',editing=null,toastHandle,completionAnnounced=false;
function num(v){const x=Number(String(v??'').replace(',','.'));return Number.isFinite(x)?x:0}
function h(v){return String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))}
function attr(v){return h(v)}
function pad(v){return String(v).padStart(2,'0')}
function fmt(d){return d.getFullYear()+'-'+pad(d.getMonth()+1)+'-'+pad(d.getDate())}
function today(){return fmt(new Date())}
function dt(v){return new Date(v+'T12:00:00')}
function add(v,n){const d=dt(v);d.setDate(d.getDate()+n);return fmt(d)}
function dow(v){return (dt(v).getDay()+6)%7}
function monday(v){return add(v,-dow(v))}
function nice(v){return dt(v).toLocaleDateString('pt-BR',{day:'2-digit',month:'short'})}
function niceLong(v){return dt(v).toLocaleDateString('pt-BR',{day:'2-digit',month:'long',year:'numeric'})}
function keyFor(date=selected,type=typeFor(date)){return date+'|'+type}
function typeFor(d=selected){return d===selected && selectedType ? selectedType : effectiveType(d)}
function baselineType(d){return state.settings?.weeklyTypes?.[dow(d)]||WD[dow(d)]}
function effectiveType(d){return state.overrides?.[d]||baselineType(d)}
function plan(type){return state.plans[type]||{kind:type==='REST'?'rest':'run',name:RX[type]||type,focus:type==='REST'?'Recuperação':'Registre ou edite seu planejamento de corrida',exercises:[]}}
function typeName(type){return plan(type).name}
function iconType(type){return icon(type==='REST'?'moon':plan(type).kind==='gym'?'dumbbell':'run',22)}
function kindType(type){return type==='REST'?'rest':plan(type).kind==='gym'?'gym':'run'}
function allSessions(){return Object.values(state.sessions).filter(s=>s&&s.date&&s.type)}
function normalized(v){if(!v||typeof v!=='object'||Array.isArray(v))throw Error('Arquivo inválido');if(v.version===1 && v.sessions && !Array.isArray(v.sessions)){
 const out=blank();out.sessions=clone(v.sessions);for(const session of Object.values(out.sessions)){if(session && out.plans[session.type]?.kind==='gym' && !session.snapshotExercises){session.snapshotExercises=clone(out.plans[session.type].exercises)}}out.migrated=true;return out
 }if(v.version!==2||!v.sessions||typeof v.sessions!=='object'||Array.isArray(v.sessions))throw Error('Backup desconhecido');const out=blank();out.sessions=v.sessions;out.plans=v.plans||out.plans;out.events=v.events||out.events;out.overrides=(v.overrides&&typeof v.overrides==='object'&&!Array.isArray(v.overrides))?v.overrides:{};out.measures=Array.isArray(v.measures)?v.measures:[];out.settings={...out.settings,...v.settings};out.timer=v.timer??null;out.migrated=!!v.migrated;
 // Preserva as exceções de data da versão anterior, sem impor essas datas a novos usuários.
 if(!v.scheduleMigrated){
   const previousSpecialDays={'2026-10-12':'EASY','2026-10-13':'REST','2026-11-17':'REST','2026-11-18':'EASY','2026-11-20':'REST'};
   for(const [date,type] of Object.entries(previousSpecialDays))if(!Object.prototype.hasOwnProperty.call(out.overrides,date))out.overrides[date]=type;
 }
 out.scheduleMigrated=true;return out}
function init(){try{const raw=localStorage.getItem(STORE);if(raw){state=normalized(JSON.parse(raw));save(false)}else{const old=localStorage.getItem(LEGACY);if(old){state=normalized(JSON.parse(old));save(false)}else save(false)}}catch(e){storageOK=false;console.warn('Não foi possível carregar o armazenamento local:',e)}monthCursor=selected.slice(0,7);status();}
function save(update=true){try{localStorage.setItem(STORE,JSON.stringify(state));storageOK=true}catch(e){storageOK=false;console.error('Falha ao salvar dados locais:',e)}if(update)status()}
function status(){const el=document.getElementById('saveStatus');if(el){el.classList.toggle('fail',!storageOK);el.innerHTML=storageOK?'<i></i> No dispositivo':'<i></i> Não salvo';}}
function toast(s){const el=document.getElementById('toast');el.textContent=s;el.classList.add('show');clearTimeout(toastHandle);toastHandle=setTimeout(()=>el.classList.remove('show'),2400)}
function getSession(create=false,date=selected,type=typeFor(date)){const k=keyFor(date,type);if(!state.sessions[k]&&create){const p=plan(type);state.sessions[k]={date,type,exercises:{},exertion:{},run:{},notes:'',startedAt:new Date().toISOString(),finishedAt:null,snapshotExercises:p.kind==='gym'?clone(p.exercises):[]}}return state.sessions[k]||null}
function exFor(type,s){return s?.snapshotExercises?.length?s.snapshotExercises:plan(type).exercises||[]}
function getSets(s,ex,create=false){if(!s)return Array.from({length:ex.sets||0},()=>({kg:'',reps:'',done:false}));if(!s.exercises)s.exercises={};if(!s.exercises[ex.id]&&create){const old=prev(s.type,ex.id,s.date)?.exercises?.[ex.id]||[];s.exercises[ex.id]=Array.from({length:ex.sets||0},(_,i)=>({kg:old[i]?.kg??'',reps:old[i]?.reps??'',done:false}));}return s.exercises[ex.id]||Array.from({length:ex.sets||0},()=>({kg:'',reps:'',done:false}))}
function sessionCounts(s,type){const p=plan(type);if(p.kind==='gym'){const exs=exFor(type,s);const total=exs.reduce((sum,e)=>sum+(getSets(s,e).length),0);const done=exs.reduce((sum,e)=>sum+getSets(s,e).filter(a=>a.done).length,0);return{done,total}}return {done:s?.run?.done?1:0,total:1}}
function populated(s){if(!s)return false;const p=plan(s.type);return p.kind==='gym'?exFor(s.type,s).some(e=>getSets(s,e).some(v=>v.done||v.kg!==''||v.reps!=='')):!!(s.run?.done||s.run?.distance||s.run?.minutes||s.notes||s.finishedAt)}
function logs(){return allSessions().filter(populated).sort((a,b)=>b.date.localeCompare(a.date))}
function prev(type,id,date){return allSessions().filter(s=>s.type===type&&s.date<date&&Array.isArray(s.exercises?.[id])&&s.exercises[id].some(v=>v.done)).sort((a,b)=>b.date.localeCompare(a.date))[0]||null}
/* Descanso automático por padrão de movimento e faixa de repetições. Os valores são heurísticos e não medem fadiga fisiológica. */
function exerciseClass(ex){
 const name=String(ex.name||'').normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase();
 if(/agach|leg press|levantamento terra|terra romeno|deadlift|stiff/.test(name))return 'lower-heavy';
 if(/afundo|bulgar|passada|lunge|hack|extensao de quadril|hip thrust|elevacao pelvica/.test(name))return 'lower-multi';
 if(/supino|barra fixa|puxada|remada|desenvolvimento|paralelas|pull.up|chest press/.test(name))return 'upper-multi';
 if(/mesa flexora|cadeira flexora|extensora|flexora|panturrilha|abduc|aduc|rosca|triceps|eleva[cç][aã]o lateral|crucifixo|peck deck|pallof|prancha|abdomen|abdominal|fly/.test(name))return 'isolation';
 return 'unknown';
}
function targetRange(ex){const m=String(ex.target||'').match(/(\d+)\s*[–-]\s*(\d+)/);return m?{min:+m[1],max:+m[2]}:null}
function restProfile(ex){const category=exerciseClass(ex),range=targetRange(ex);let seconds=90,reason='exercício geral';
 if(category==='lower-heavy'){seconds=range?.max<=8?180:150;reason='multiarticular pesado de pernas'}
 else if(category==='lower-multi'){seconds=150;reason='multiarticular de pernas / quadril'}
 else if(category==='upper-multi'){seconds=range?.max<=8?150:120;reason='multiarticular de superiores'}
 else if(category==='isolation'){seconds=range?.min>=12?75:90;reason='exercício isolador / estabilidade'}
 else if(range?.max<=8){seconds=150;reason='faixa de força'}
 else if(range?.max<=12){seconds=120;reason='faixa moderada'}
 else{seconds=90;reason='faixa de repetições mais alta'}
 return {seconds,reason,category};
}
function autoRest(ex,sets,index){const profile=restProfile(ex),current=sets[index],range=targetRange(ex);let seconds=profile.seconds,extra='';
 if(range && num(current?.reps)>0 && num(current.reps)<range.min){seconds+=30;extra=' · +30 s por repetições abaixo da faixa'}
 else if(index>0 && num(current?.kg)>num(sets[index-1]?.kg) && num(sets[index-1]?.kg)>0){seconds+=15;extra=' · +15 s por aumento de carga'}
 return {seconds:Math.min(240,seconds),reason:profile.reason+extra};
}
function fmtRest(sec){return `${Math.floor(sec/60)}min${sec%60?` ${pad(sec%60)}s`:''}`}
function maxTarget(ex){const m=String(ex.target).match(/\d+\s*[–-]\s*(\d+)/);return m?Number(m[1]):null}
function suggestion(ex,type,date){const p=prev(type,ex.id,date);if(!p)return '';const ss=p.exercises[ex.id]||[];const upper=maxTarget(ex);if(!upper||!ss.length||!ss.every(v=>v.done&&num(v.reps)>=upper&&v.kg!==''))return '';const rir=p.exertion?.[ex.id];const inc=ex.step||state.settings.defaultIncrement||2.5;const lastKg=num(ss[0].kg);if(rir!==undefined&&rir!==''&&num(rir)>=1)return `✓ Meta anterior completa (RIR ${rir}). Considere ${fmtNum(lastKg+inc)} kg na próxima sessão, se a técnica estiver boa.`;return `Meta de repetições atingida. Se a técnica estiver boa e sobraram 1–2 reps, considere +${fmtNum(inc)} kg.`}
function fmtNum(x){return Number(x).toLocaleString('pt-BR',{maximumFractionDigits:2})}
function currentEvent(d){return state.events[d]||null}
function upcomingRace(d){return Object.entries(state.events).find(([day,event])=>event?.kind==='race'&&day>=d&&day<=add(d,5))?.[0]||null}
function weekTotals(d){let gym=0,run=0,sets=0;const from=monday(d),to=add(from,6);for(const s of logs().filter(s=>s.date>=from&&s.date<=to)){const p=plan(s.type);if(p.kind==='gym'){if(sessionCounts(s,s.type).done)gym++;sets+=sessionCounts(s,s.type).done}else if(s.run?.done){run+=num(s.run?.distance)}}return {gym,run,sets}}
function completedStats(){const s=logs();const volume=s.reduce((sum,v)=>{if(plan(v.type).kind!=='gym')return sum;return sum+exFor(v.type,v).reduce((x,e)=>x+getSets(v,e).filter(a=>a.done).reduce((y,a)=>y+num(a.kg)*num(a.reps),0),0)},0);const distance=s.filter(v=>v.run?.done).reduce((a,v)=>a+num(v.run.distance),0);return {gym:s.filter(v=>plan(v.type).kind==='gym'&&sessionCounts(v,v.type).done>0).length,run:s.filter(v=>v.run?.done).length,volume,distance}}
function selectDate(d){selected=d;selectedType=null;monthCursor=d.slice(0,7);tab='training';render();window.scrollTo({top:0,behavior:'smooth'})}
function selectCalendarDate(d){selected=d;selectedType=null;monthCursor=d.slice(0,7);tab='calendar';render();document.getElementById('agendaDetail')?.scrollIntoView?.({behavior:'smooth',block:'nearest'})}
function setTab(t){tab=t;render();window.scrollTo({top:0,behavior:'instant'})}
function navMarkup(){document.querySelectorAll('[data-tab]').forEach(btn=>btn.classList.toggle('active',btn.dataset.tab===tab))}
function titleArea(kicker,title,detail=''){return `<section class="hero"><div class="eyebrow">${h(kicker)}</div><h1>${title}</h1>${detail?`<p>${h(detail)}</p>`:''}</section>`}
function render(){navMarkup();const el=document.getElementById('app');el.innerHTML=tab==='home'?renderHome():tab==='training'?renderTraining():tab==='calendar'?renderCalendar():tab==='progress'?renderProgress():renderSettings();updateTimerDock()}
function typeCard(d,type,small=false){const p=plan(type),cl=kindType(type),e=currentEvent(d),lbl=cl==='run'&&e?e.title:p.name;return `<div class="workoutcard"><div class="badgeicon ${cl}">${iconType(type)}</div><div class="flex1"><h3>${h(lbl)}</h3><p>${cl==='run'?`${e?.distance?h(e.distance)+' km · ':''}${h(p.focus)}`:h(p.focus)}</p></div><span class="chip ${cl==='run'?'orange':cl==='gym'?'lime':''}">${cl==='gym'?'GYM':cl==='run'?'CORRIDA':'OFF'}</span>${small?'':`<button class="btn alt sm" data-action="pick" data-date="${d}">Abrir</button>`}</div>`}
function weeklyActivityRings(d){
 const dates=Array.from({length:7},(_,i)=>add(monday(d),i));
 const gymGoal=dates.filter(x=>plan(effectiveType(x)).kind==='gym').length;
 const runGoal=dates.filter(x=>plan(effectiveType(x)).kind==='run').length;
 const entries=logs().filter(s=>dates.includes(s.date));
 const gymDone=new Set(entries.filter(s=>plan(s.type).kind==='gym'&&sessionCounts(s,s.type).done>0).map(s=>s.date)).size;
 const runDone=new Set(entries.filter(s=>plan(s.type).kind==='run'&&s.run?.done).map(s=>s.date)).size;
 const goal=gymGoal+runGoal,done=gymDone+runDone;
 const ring=(label,value,total,accent,glow,description)=>{
  const percent=total?Math.max(0,Math.min(100,Math.round(value/total*100))):0;
  return `<div class="ring-card"><div class="activity-ring" role="progressbar" aria-label="${label}" aria-valuenow="${value}" aria-valuemin="0" aria-valuemax="${total}" style="--ring-color:${accent};--ring-glow:${glow};--ring-fill:${percent}%"><div class="ring-center"><strong>${value}<small>/${total}</small></strong><small>${percent}%</small></div></div><b>${label}</b><span class="ring-caption">${description}</span></div>`;
 };
 return `<section class="activity-panel" aria-label="Atividade da semana"><div class="activity-head"><div><h2>Seus anéis</h2><p>Consistência desta semana</p></div><span class="activity-period">${nice(monday(d))} – ${nice(add(monday(d),6))}</span></div><div class="activity-rings">${ring('Força',gymDone,gymGoal,'#32D74B','rgba(50,215,75,.10)','Dias com séries')}${ring('Corrida',runDone,runGoal,'#FF2D55','rgba(255,45,85,.10)','Corridas feitas')}${ring('Atividade',done,goal,'#0A84FF','rgba(10,132,255,.10)','Dias ativos')}</div><div class="activity-footer"><span class="activity-dot"></span>Força &nbsp; <span class="activity-dot run"></span>Corrida &nbsp; <span class="activity-dot all"></span>Total · conforme sua rotina semanal</div></section>`;
}
function renderHome(){const c=weekTotals(selected),st=completedStats();const d=selected;return `${titleArea('FORÇA + RESISTÊNCIA','Mais forte.<br><span class="mint">Mais longe.</span>','Sua evolução começa na próxima série. Todos os treinos em um só lugar.')}
 ${weeklyActivityRings(d)}
 <div class="grid3"><div class="metric"><strong>${c.gym}</strong><span>Treinos de força na semana</span></div><div class="metric"><strong>${fmtNum(c.run)}</strong><span>Km feitos nesta semana</span></div><div class="metric"><strong>${c.sets}</strong><span>Séries concluídas</span></div></div>
 <div class="section"><h2>Esta semana</h2><button class="btn ghost" data-action="go-tab" data-target="calendar">Ver agenda →</button></div>
 <div class="panel"><div class="weeknav"><div class="weeklabel">${nice(monday(d))} — ${nice(add(monday(d),6))}</div><span class="chip">${niceLong(d)}</span></div>${weekStrip(d)}</div>
 <div class="section"><h2>Seu treino</h2><span class="chip lime">${DAYS[dow(d)]}</span></div>${typeCard(d,effectiveType(d))}
 <button class="btn block" data-action="pick" data-date="${d}">Abrir treino de hoje →</button>
 <div class="section"><h2>Próximos dias</h2></div>${[1,2,3].map(k=>`<div class="listrow"><div><b>${DAYS[dow(add(d,k))]} · ${nice(add(d,k))}</b><small>${h(plan(effectiveType(add(d,k))).name)} ${currentEvent(add(d,k))?'· '+h(currentEvent(add(d,k)).title):''}</small></div><button class="btn alt sm" data-action="pick" data-date="${add(d,k)}">Abrir</button></div>`).join('')}
 <div class="section"><h2>Visão geral</h2></div><div class="grid2"><div class="metric"><strong>${st.gym}</strong><span>Treinos de força registrados</span></div><div class="metric"><strong>${fmtNum(st.distance)}</strong><span>Km acumulados registrados</span></div></div>`}
function weekStrip(d){const m=monday(d);return `<div class="days">${DAYS.map((name,i)=>{const x=add(m,i),s=getSession(false,x,effectiveType(x)),has=populated(s),run=plan(effectiveType(x)).kind==='run';return `<button class="day ${x===selected?'active':''} ${x===today()?'today':''} ${run?'hasrun':''}" data-action="pick" data-date="${x}"><b>${name}</b><strong>${dt(x).getDate()}</strong><i>${has?'●':run?'●':'·'}</i></button>`}).join('')}</div>`}
function renderTraining(){const d=selected,type=typeFor(d),p=plan(type),s=getSession(false),c=sessionCounts(s,type),e=currentEvent(d);let out=`${titleArea('SESSÃO / '+DAYS[dow(d)],h(p.name),p.focus)}<div class="panel"><div class="weeknav"><div class="weeklabel">${nice(monday(d))} — ${nice(add(monday(d),6))}</div><div class="row"><button class="btn alt sm square" data-action="shift-week" data-n="-7" aria-label="Semana anterior">${icon('chev-left',19)}</button><button class="btn alt sm square" data-action="pick" data-date="${today()}" aria-label="Hoje">${icon('home',16)}</button><button class="btn alt sm square" data-action="shift-week" data-n="7" aria-label="Próxima semana">${icon('chev-right',19)}</button></div></div>${weekStrip(d)}
 <label class="fieldlabel" for="typeSelect">Treino desta data (mudanças salvas)</label><select id="typeSelect" data-action="switch-type" style="width:100%">${Object.keys({...state.plans,EASY:1,QUALITY:1,LONG:1,REST:1}).map(t=>`<option value="${t}" ${t===type?'selected':''}>${h(typeName(t))}</option>`).join('')}</select></div>`;
 if(p.kind==='gym'){const exercises=exFor(type,s);out+=`<div class="panel"><div class="row between"><div><div class="eyebrow">Acompanhamento da sessão</div><h2 style="margin:5px 0">${c.done} / ${c.total} séries</h2></div><span class="chip lime">${Math.round(c.done/Math.max(c.total,1)*100)}% concluído</span></div><div class="progress"><i style="width:${c.done/Math.max(c.total,1)*100}%"></i></div><div class="row between" style="margin-top:12px"><span class="small subtle">Cargas por série e descanso automático</span><button class="btn ghost sm" data-action="editor" data-type="${type}">${icon('edit',15)} Editar ficha</button></div></div>`;
 if(type==='B'){const race=upcomingRace(d);if(race)out+=`<div class="callout warn" style="margin-bottom:12px">Prova programada para ${niceLong(race)}: considere reduzir ou evitar pernas pesadas nos dias anteriores. Priorize sua recuperação.</div>`;}
 out+=exercises.map((ex,i)=>renderExercise(ex,i,s,type)).join('');out+=`<div class="panel"><label class="fieldlabel" for="sessNotes">Notas da sessão</label><textarea id="sessNotes" data-input="notes" placeholder="Sono, energia, dores, percepção do treino...">${h(s?.notes||'')}</textarea><div class="row between" style="margin-top:12px"><span class="small subtle">${s?.finishedAt?'Finalizado · registro editável':'Os dados são salvos ao preencher'}</span><button class="btn sm" data-action="finish" ${c.done===0?'disabled':''}>${s?.finishedAt?'Atualizar finalização':'Finalizar sessão ✓'}</button></div></div>`
 }else if(kindType(type)==='run'){out+=`<div class="panel">${e?`<div class="runbox"><b>${h(e.title)}</b><span>${e.distance?h(e.distance)+' km · ':''}${e.source==='ics'?'Calendário importado':'Treino planejado'}${e.details?' · '+h(e.details):''}</span></div>`:'<div class="callout warn">Nenhum planejamento cadastrado para esta data. Use “Editar corrida” para adicionar distância, ritmo e detalhes, se desejar.</div>'}
 <div class="row between" style="margin:13px 0"><span class="small subtle">Planejamento da corrida</span><button class="btn alt sm" data-action="run-edit" data-date="${d}">${icon('edit',15)} Editar corrida</button></div><div class="formgrid"><div><label class="fieldlabel">Distância realizada (km)</label><input type="number" step="0.1" min="0" data-input="run" data-field="distance" value="${attr(s?.run?.distance||'')}" placeholder="${attr(e?.distance||'0')}"></div><div><label class="fieldlabel">Tempo realizado (min)</label><input type="number" step="0.1" min="0" data-input="run" data-field="minutes" value="${attr(s?.run?.minutes||'')}" placeholder="Ex.: 36,5"></div></div>
 <label class="fieldlabel">Esforço percebido (RPE)</label><select data-input="run" data-field="rpe"><option value="">Selecionar...</option>${Array.from({length:10},(_,i)=>i+1).map(n=>`<option value="${n}" ${String(s?.run?.rpe||'')===String(n)?'selected':''}>${n} / 10</option>`).join('')}</select>
 <label class="fieldlabel">Notas</label><textarea data-input="notes" placeholder="Como foi a corrida?">${h(s?.notes||'')}</textarea>
 <button class="btn block" style="margin-top:14px" data-action="complete-run">${s?.run?.done?'✓ Corrida concluída — toque para desfazer':'✓ Marcar corrida concluída'}</button></div>`
 }else out+=`<div class="panel"><h2>Recuperação também é treino.</h2><p class="subtle small">Durma bem, hidrate-se e mantenha a mobilidade se estiver confortável. Ajuste o descanso às suas necessidades e aos treinos seguintes.</p><label class="fieldlabel">Notas (opcional)</label><textarea data-input="notes" placeholder="Como você está se sentindo hoje?">${h(s?.notes||'')}</textarea></div>`;
 return out}
function renderExercise(ex,i,s,type){const sets=getSets(s,ex),done=sets.filter(v=>v.done).length,last=prev(type,ex.id,selected),prevSets=last?.exercises?.[ex.id]||[],advice=suggestion(ex,type,selected),rir=s?.exertion?.[ex.id]??'';
 return `<div class="exercise ${done===sets.length&&sets.length?'complete':''}" id="ex-${attr(ex.id)}"><div class="ehead"><span class="enum">${pad(i+1)}</span><div class="flex1"><h3>${h(ex.name)}</h3><p>${sets.length} séries · ${h(ex.target)} reps · ${fmtRest(restProfile(ex).seconds)} descanso automático</p></div><span class="chip ${done===sets.length&&sets.length?'lime':''}">${done}/${sets.length}</span></div>
 <div class="lastline"><span>${last?`Anterior ${nice(last.date)}: ${h(prevSets.map(v=>(v.kg||'—')+'kg×'+(v.reps||'—')).slice(0,2).join(' · '))}`:'Sem histórico anterior'}</span>${last?`<button class="btn ghost sm" data-action="copy-previous" data-id="${attr(ex.id)}">Repetir →</button>`:''}</div>
 <div class="sethead"><span>#</span><span>PESO (kg)</span><span>REPS</span><span>OK</span></div>
 ${sets.map((v,j)=>`<div class="setline ${v.done?'done':''}"><span class="setindex">${j+1}</span><div class="counter"><button aria-label="Diminuir peso" data-action="adjust" data-id="${attr(ex.id)}" data-i="${j}" data-field="kg" data-delta="-${Number(ex.step||2.5)}">−</button><input aria-label="Peso série ${j+1} em kg" type="number" step="any" inputmode="decimal" data-input="set" data-id="${attr(ex.id)}" data-i="${j}" data-field="kg" value="${attr(v.kg??'')}" placeholder="kg"><button aria-label="Aumentar peso" data-action="adjust" data-id="${attr(ex.id)}" data-i="${j}" data-field="kg" data-delta="${Number(ex.step||2.5)}">+</button></div><div class="counter"><button aria-label="Diminuir repetições" data-action="adjust" data-id="${attr(ex.id)}" data-i="${j}" data-field="reps" data-delta="-1">−</button><input aria-label="Repetições série ${j+1}" type="number" inputmode="numeric" min="0" data-input="set" data-id="${attr(ex.id)}" data-i="${j}" data-field="reps" value="${attr(v.reps??'')}" placeholder="reps"><button aria-label="Aumentar repetições" data-action="adjust" data-id="${attr(ex.id)}" data-i="${j}" data-field="reps" data-delta="1">+</button></div><button aria-label="${v.done?'Desmarcar':'Concluir'} série ${j+1}" class="mark ${v.done?'done':''}" data-action="toggle-set" data-id="${attr(ex.id)}" data-i="${j}">${v.done?'✓':'○'}</button></div>`).join('')}
 <div class="exerciseactions"><label class="tiny subtle" for="rir-${attr(ex.id)}">Reps em reserva (RIR):</label><select style="min-height:32px;padding:6px;width:auto" id="rir-${attr(ex.id)}" data-input="rir" data-id="${attr(ex.id)}"><option value="">—</option>${[0,1,2,3,4,5].map(n=>`<option value="${n}" ${String(rir)===String(n)?'selected':''}>${n}</option>`).join('')}</select><span class="resthint">${icon('clock',15)} ${fmtRest(restProfile(ex).seconds)} · automático</span></div>
 ${advice?`<div class="hints positive">${h(advice)}</div>`:''}</div>`}
function calendarDayDetails(d){const type=effectiveType(d),p=plan(type),s=getSession(false,d,type),c=sessionCounts(s,type),e=currentEvent(d),k=kindType(type);
 const workouts=k==='gym'?`<div class="agenda-preview"><div class="small subtle">${c.done} de ${c.total} séries concluídas</div><div class="progress" style="margin:9px 0"><i style="width:${Math.round(c.done/Math.max(1,c.total)*100)}%"></i></div>${exFor(type,s).map(ex=>`<div class="agenda-ex-row"><span>${h(ex.name)}</span><small>${ex.sets} × ${h(ex.target)}</small></div>`).join('')}</div>`:
 k==='run'?`<div class="agenda-preview">${e?`<div class="small"><b>${h(e.title)}</b>${e.distance?' · '+h(e.distance)+' km':''}</div>${e.details?`<p class="small subtle" style="margin:7px 0">${h(e.details)}</p>`:''}`:'<p class="small subtle">Nenhuma corrida planejada para este dia.</p>'}${s?.run?.done?`<div class="chip lime" style="display:inline-flex;margin-top:8px">${icon('check',14)} Corrida concluída · ${h(s.run.distance||'—')} km</div>`:''}</div>`:
 '<div class="agenda-preview small subtle">Dia de recuperação programado.</div>';
 return `<div class="agenda-detail"><div class="workoutcard"><div class="badgeicon ${k}">${iconType(type)}</div><div class="flex1"><h3>${h(p.name)}</h3><p>${h(p.focus)}</p></div><span class="chip">${k==='gym'?'FORÇA':k==='run'?'CORRIDA':'OFF'}</span></div>${workouts}<div class="agenda-buttons">${k==='run'?`<button class="btn alt sm" data-action="run-edit" data-date="${d}">${icon('edit',16)} Planejar</button>`:''}<button class="btn sm" data-action="pick" data-date="${d}">${icon('right',16)} ${k==='rest'?'Abrir dia':'Registrar treino'}</button></div></div>`;
}
function renderCalendar(){const first=monthCursor+'-01',ym=dt(first),last=new Date(ym.getFullYear(),ym.getMonth()+1,0).getDate(),offset=dow(first),count=Math.ceil((offset+last)/7)*7;const tiles=Array.from({length:count},(_,i)=>{const d=add(first,i-offset),other=d.slice(0,7)!==monthCursor,ty=effectiveType(d),e=currentEvent(d),s=getSession(false,d,ty);return `<button class="day ${d===selected?'active':''} ${d===today()?'today':''} ${kindType(ty)==='run'?'hasrun':''}" style="opacity:${other?'.4':'1'}" data-action="cal-pick" data-date="${d}"><b>${DAYS[dow(d)]}</b><strong>${dt(d).getDate()}</strong><i>${populated(s)?'●':e?'●':'·'}</i></button>`}).join('');const evs=Object.entries(state.events).filter(([d])=>d.startsWith(monthCursor)).sort(([a],[b])=>a.localeCompare(b));return `${titleArea('CALENDÁRIO','Sua agenda.<br><span class="mint">Seu ritmo.</span>','Organize musculação, corridas e provas. Adicione ou importe seus próprios eventos.')}
 <div class="panel"><div class="weeknav"><button class="btn alt sm square" data-action="move-month" data-n="-1" aria-label="Mês anterior">${icon('chev-left',19)}</button><h2 style="margin:0;text-transform:capitalize">${ym.toLocaleDateString('pt-BR',{month:'long',year:'numeric'})}</h2><button class="btn alt sm square" data-action="move-month" data-n="1" aria-label="Próximo mês">${icon('chev-right',19)}</button></div><div class="days">${tiles}</div><div class="row" style="margin-top:14px;justify-content:space-between"><span class="small subtle">● Marcado / planejado</span><button class="btn alt sm" data-action="go-today">Hoje</button></div></div>
 <div class="row" style="margin:14px 0;gap:8px"><button class="btn alt sm flex1" data-action="run-edit" data-date="${selected}">${icon('plus',16)} Cadastrar corrida</button><button class="btn alt sm flex1" data-action="import-ics">${icon('upload',16)} Importar .ics</button></div>
 <div class="section" id="agendaDetail"><h2>${niceLong(selected)}</h2></div>${calendarDayDetails(selected)}

 <div class="section"><h2>Corridas deste mês</h2><span class="chip">${evs.length} eventos</span></div>
 <div class="panel">${evs.length?evs.map(([d,e])=>`<div class="listrow"><div><b>${nice(d)} · ${h(e.title)}</b><small>${h(e.distance||'—')} km · ${h(e.source==='ics'?'Calendário importado':'Cadastrado')}</small></div><button class="btn alt sm" data-action="run-edit" data-date="${d}">Editar</button></div>`).join(''):'<div class="empty">Nenhum evento cadastrado neste mês.</div>'}</div>
 <div class="callout">Você pode cadastrar suas corridas ou importar eventos de um arquivo .ics. A importação é manual e não sincroniza automaticamente com aplicativos externos.</div>`}
function graphPoints(rows,suffix=''){if(!rows.length)return '<div class="empty">Ainda não há registros suficientes para gerar o gráfico.</div>';const vals=rows.map(r=>r.value),hi=Math.max(...vals,1),lo=Math.min(...vals,0),span=Math.max(hi-lo,1),x0=32,xw=314;const points=rows.map((r,i)=>[x0+(rows.length===1?xw/2:i*xw/(rows.length-1)),133-((r.value-lo)/span)*95]);const pts=points.map(x=>x.join(',')).join(' ');return `<svg class="graph" viewBox="0 0 385 176" role="img" aria-label="Gráfico de evolução"><line class="gridline" x1="32" x2="346" y1="37" y2="37"/><line class="gridline" x1="32" x2="346" y1="133" y2="133"/><text x="2" y="39">${fmtNum(hi)}${suffix}</text><text x="2" y="136">${fmtNum(lo)}</text><polyline points="${pts}"/>${points.map((p,i)=>`<circle r="4" cx="${p[0]}" cy="${p[1]}"/><text x="${p[0]}" y="159" text-anchor="middle">${rows[i].date.slice(8)}/${rows[i].date.slice(5,7)}</text>`).join('')}</svg>`}
function exerciseChoices(){return Object.entries(state.plans).flatMap(([type,p])=>p.exercises.map(e=>({key:type+'|'+e.id,name:e.name,plan:p.name}))) }
function exData(){const [type,id]=chartExercise.split('|');return logs().filter(s=>s.type===type&&Array.isArray(s.exercises?.[id])).map(s=>{const a=s.exercises[id].filter(v=>v.done&&v.kg!==''&&num(v.reps)>0);return {date:s.date,value:Math.max(0,...a.map(v=>num(v.kg)))}}).filter(x=>x.value>0).sort((a,b)=>a.date.localeCompare(b.date)).slice(-9)}
function personalRecords(){const result=[];for(const [type,p] of Object.entries(state.plans)){for(const ex of p.exercises){let best=null;for(const s of allSessions().filter(x=>x.type===type)){for(const v of s.exercises?.[ex.id]||[]){if(v.done&&v.kg!==''&&num(v.reps)>0){const kg=num(v.kg),estimated=kg*(1+num(v.reps)/30);if(!best||estimated>best.estimated)best={kg,reps:num(v.reps),date:s.date,estimated}}}}if(best)result.push({name:ex.name,...best})}}return result.sort((a,b)=>b.estimated-a.estimated)}
function sevenDayRunDistance(){const out=[];const anchor=monday(today());for(let n=5;n>=0;n--){const start=add(anchor,-7*n),end=add(start,6);let km=0;for(const s of logs().filter(x=>x.date>=start&&x.date<=end&&x.run?.done))km+=num(s.run.distance);out.push({name:n===0?'Esta':'-'+n,value:km})}return out}
function sevenDayVolumes(){const out=[];let anchor=monday(today());for(let n=5;n>=0;n--){const start=add(anchor,-7*n),end=add(start,6);let vol=0;for(const s of logs().filter(x=>x.date>=start&&x.date<=end&&plan(x.type).kind==='gym'))for(const ex of exFor(s.type,s))for(const v of getSets(s,ex))if(v.done)vol+=num(v.kg)*num(v.reps);out.push({name:n===0?'Esta':'-'+n,value:vol})}return out}
function renderProgress(){const st=completedStats(),choices=exerciseChoices(),exs=exData(),pr=personalRecords(),weekly=sevenDayVolumes(),weeklyRun=sevenDayRunDistance(),max=Math.max(1,...weekly.map(x=>x.value)),maxRun=Math.max(1,...weeklyRun.map(x=>x.value));const measurements=[...state.measures].sort((a,b)=>a.date.localeCompare(b.date));return `${titleArea('DADOS / CONSISTÊNCIA','A evolução<br><span class="mint">não mente.</span>','Histórico de força, volume de treino, corrida e medidas corporais.')}
 <div class="grid2"><div class="metric"><strong>${st.gym}</strong><span>Sessões de musculação</span></div><div class="metric"><strong>${fmtNum(st.distance)} <span class="small">km</span></strong><span>Quilômetros registrados</span></div><div class="metric"><strong>${fmtNum(st.volume)}</strong><span>Volume externo total (kg × reps)</span></div><div class="metric"><strong>${pr.length}</strong><span>Exercícios com registros de carga</span></div></div>
 <div class="section"><h2>Cargas por exercício</h2></div><div class="panel"><label class="fieldlabel" style="margin-top:0">Selecione o exercício</label><select data-action="chart-select" style="width:100%">${choices.map(e=>`<option value="${h(e.key)}" ${e.key===chartExercise?'selected':''}>${h(e.name)} — ${h(e.plan)}</option>`).join('')}</select>${graphPoints(exs,'kg')}<div class="small subtle">Maior carga concluída registrada em cada sessão. Peso por halter ou total: mantenha o mesmo padrão.</div></div>
 <div class="section"><h2>Volume semanal</h2></div><div class="panel"><div class="barlist">${weekly.map(w=>`<div class="barline"><label>${w.name}</label><div><i style="width:${w.value/max*100}%"></i></div><b>${fmtNum(w.value)} kg</b></div>`).join('')}</div><p class="small subtle" style="margin:12px 0 0">Soma de carga externa × repetições das séries concluídas; não equivale à carga fisiológica total.</p></div>
 <div class="section"><h2>Corrida semanal</h2></div><div class="panel"><div class="barlist">${weeklyRun.map(w=>`<div class="barline"><label>${w.name}</label><div><i class="runbar" style="width:${w.value/maxRun*100}%"></i></div><b>${fmtNum(w.value)} km</b></div>`).join('')}</div><p class="small subtle" style="margin:12px 0 0">Distâncias efetivamente registradas, não os quilômetros planejados.</p></div>
 <div class="section"><h2>Seus recordes</h2></div><div class="panel">${pr.length?pr.slice(0,15).map(x=>`<div class="listrow"><div><b>${h(x.name)}</b><small>${nice(x.date)} · ${fmtNum(x.reps)} reps · 1RM estimado ${fmtNum(x.estimated)} kg</small></div><span class="chip lime">${fmtNum(x.kg)} kg</span></div>`).join(''):'<div class="empty">Complete algumas séries para gerar recordes.</div>'}</div>
 <div class="section"><h2>Medidas corporais</h2><button class="btn alt sm" data-action="add-measure">+ Adicionar</button></div><div class="panel">${measurements.length?`${graphPoints(measurements.filter(x=>x.weight!==''&&x.weight!=null).map(x=>({date:x.date,value:num(x.weight)})).slice(-9),'kg')}${measurements.slice(-8).reverse().map(m=>`<div class="listrow"><div><b>${nice(m.date)} · ${h(m.weight||'—')} kg</b><small>Cintura: ${h(m.waist||'—')} cm · Braço: ${h(m.arm||'—')} cm · Peito: ${h(m.chest||'—')} cm</small></div><button class="btn alt sm" data-action="delete-measure" data-date="${m.date}">Excluir</button></div>`).join('')}`:'<div class="empty">Acompanhe peso e circunferências para ver ganhos musculares.</div>'}</div>
 <div class="section"><h2>Treinos anteriores</h2></div><div class="panel">${logs().length?logs().slice(0,30).map(s=>{const p=plan(s.type),c=sessionCounts(s,s.type);return `<div class="listrow"><div><b>${nice(s.date)} · ${h(p.name)}</b><small>${p.kind==='gym'?c.done+' de '+c.total+' séries':s.run?.done?(s.run.distance||'—')+' km':'Anotação'}</small></div><button class="btn alt sm" data-action="history-pick" data-date="${s.date}" data-type="${s.type}">Abrir</button></div>`}).join(''):'<div class="empty">Os registros aparecerão aqui.</div>'}</div>`}
function renderSettings(){return `${titleArea('CONFIGURAÇÕES','Seu app.<br><span class="mint">Suas regras.</span>','Personalize treinos e descanso. Seus dados continuam armazenados neste aparelho.')}
 <div class="section"><h2>Suas fichas</h2></div>${Object.entries(state.plans).map(([id,p])=>`<div class="workoutcard"><div class="badgeicon">${icon('dumbbell',22)}</div><div class="flex1"><h3>${h(p.name)}</h3><p>${p.exercises.length} exercícios · ${h(p.focus)}</p></div><button class="btn alt sm" data-action="editor" data-type="${id}">Editar</button></div>`).join('')}
 <div class="section"><h2>Rotina semanal</h2></div><div class="panel"><p class="small subtle">Defina seu treino padrão para cada dia da semana. Essas mudanças valem para todas as semanas. Alterações específicas de uma data continuam disponíveis na Agenda e em Treinar.</p>
 ${DAYS.map((day,i)=>`<div class="weeklyrow"><label for="weekly-${i}">${day}</label><select id="weekly-${i}" data-input="weekly" data-day="${i}">${Object.keys({...state.plans,EASY:1,QUALITY:1,LONG:1,REST:1}).map(t=>`<option value="${t}" ${baselineType(add(monday(today()),i))===t?'selected':''}>${h(typeName(t))}</option>`).join('')}</select></div>`).join('')}</div>
 <div class="section"><h2>Durante o treino</h2></div><div class="panel"><p class="small subtle">O descanso é calculado automaticamente pelo movimento e pela faixa de repetições: compostos pesados geralmente 2–3 min, isoladores 1–1,5 min. Uma série abaixo da faixa acrescenta 30 s. O app não mede sua recuperação real.</p><div class="switchrow"><label for="autoTimer">Cronômetro automático após concluir série</label><input type="checkbox" id="autoTimer" data-input="setting" data-field="timer" ${state.settings.timer?'checked':''}></div><div class="switchrow"><label for="soundTimer">Som ao terminar descanso (somente com app ativo)</label><input type="checkbox" id="soundTimer" data-input="setting" data-field="sound" ${state.settings.sound?'checked':''}></div><label class="fieldlabel">Incremento sugerido padrão (kg)</label><input style="width:100%" type="number" step="0.5" min="0.5" data-input="setting" data-field="defaultIncrement" value="${attr(state.settings.defaultIncrement||2.5)}"></div>
 <div class="section"><h2>Dados e backups</h2></div><div class="panel"><div class="callout warn" style="margin-bottom:12px">Sem Supabase por enquanto: os registros ficam somente no armazenamento deste navegador/ícone instalado. Faça backup JSON regularmente, principalmente antes de trocar de celular ou limpar os dados do Safari.</div><div class="stack"><button class="btn block" data-action="export-json">${icon('download',16)} Exportar backup completo (.json)</button><button class="btn alt block" data-action="import-json">${icon('upload',16)} Restaurar backup v1 ou v2</button><button class="btn alt block" data-action="export-csv">${icon('download',16)} Exportar séries e corridas (.csv)</button><button class="btn alt block" data-action="import-ics">${icon('upload',16)} Importar calendário (.ics)</button></div><p class="small subtle" style="margin:12px 0 0">O backup inclui fichas editadas, séries, corridas, medidas e configurações. Restaurar substitui o estado atual após confirmação. A versão antiga é preservada na chave local original.</p></div>
 <div class="section"><h2>Sincronização na nuvem</h2></div><div class="panel"><span class="chip">ETAPA FINAL — SUPABASE</span><p class="small subtle" style="margin:12px 0 0">A integração ficará para depois da validação de todas as funcionalidades. Não é necessário instalar ou configurar banco de dados agora.</p></div>
 <button class="btn alt block" data-action="reload-app">${icon('refresh',16)} Verificar atualização do app</button><button class="btn red block" style="margin-top:10px" data-action="clear">Apagar somente dados desta versão</button><p class="small subtle" style="text-align:center;margin:12px 0 0">HYBRID Training 2.3 · Os dados continuam somente neste aparelho</p>`}
function showModal(inner){document.getElementById('modalRoot').innerHTML=`<div class="overlay" data-action="close-outside"><div class="sheet" role="dialog" aria-modal="true">${inner}</div></div>`}
function dismiss(){document.getElementById('modalRoot').innerHTML='';editing=null}
function modalHeader(kicker,title){return `<div class="sheethead"><div><div class="eyebrow">${h(kicker)}</div><h2>${h(title)}</h2></div><button class="btn alt sm square" data-action="close-modal" aria-label="Fechar">${icon('x',18)}</button></div><div class="sep"></div>`}
function editor(type){if(!state.plans[type])return;editing={type};const p=plan(type);showModal(modalHeader('EDITOR DE TREINO',p.name)+`<div class="callout" style="margin-bottom:12px">Mudanças na ficha valem para novas sessões. Treinos já registrados mantêm os exercícios anteriores.</div><label class="fieldlabel">Nome da ficha</label><input id="planName" style="width:100%" value="${attr(p.name)}"><label class="fieldlabel">Foco da ficha</label><input id="planFocus" style="width:100%" value="${attr(p.focus)}"><button class="btn alt block" style="margin:12px 0" data-action="save-plan" data-type="${type}">Salvar nome e foco</button><div class="sep"></div><h3>Exercícios (${p.exercises.length})</h3>${p.exercises.map((e,i)=>`<div class="editrow"><div class="flex1"><b style="font-size:13px">${h(e.name)}</b><div class="tiny subtle">${e.sets} séries · ${h(e.target)} · ${fmtRest(restProfile(e).seconds)} auto</div></div><div class="actions"><button data-action="move-ex" data-type="${type}" data-id="${attr(e.id)}" data-n="-1" aria-label="Mover para cima" ${i===0?'disabled':''}>${icon('up',16)}</button><button data-action="move-ex" data-type="${type}" data-id="${attr(e.id)}" data-n="1" aria-label="Mover para baixo" ${i===p.exercises.length-1?'disabled':''}>${icon('down',16)}</button><button data-action="edit-ex" data-type="${type}" data-id="${attr(e.id)}" aria-label="Editar exercício">${icon('edit',16)}</button><button class="danger" data-action="delete-ex" data-type="${type}" data-id="${attr(e.id)}" aria-label="Excluir exercício">${icon('x',16)}</button></div></div>`).join('')}<div class="sheetfooter"><button class="btn block" data-action="edit-ex" data-type="${type}" data-id="">+ Adicionar exercício</button></div>`)}
function editEx(type,id=''){const ex=state.plans[type]?.exercises.find(e=>e.id===id)||{name:'',sets:3,target:'8–12',rest:90,step:2.5};editing={type,id};showModal(modalHeader('FICHA '+type,id?'Editar exercício':'Novo exercício')+`<label class="fieldlabel">Nome do exercício</label><input id="exName" maxlength="120" style="width:100%" value="${attr(ex.name)}" placeholder="Ex.: Remada unilateral"><div class="formgrid"><div><label class="fieldlabel">Séries</label><input id="exSets" type="number" min="1" max="12" value="${attr(ex.sets)}"></div><div><label class="fieldlabel">Faixa de reps</label><input id="exTarget" maxlength="40" value="${attr(ex.target)}"></div><div><label class="fieldlabel">Incremento peso (kg)</label><input id="exStep" type="number" min="0.5" max="100" step="0.5" value="${attr(ex.step)}"></div></div><div class="sheetfooter"><button class="btn block" data-action="save-ex" data-type="${type}" data-id="${attr(id)}">Salvar exercício ✓</button><button class="btn alt block" style="margin-top:8px" data-action="editor" data-type="${type}">Voltar à ficha</button></div>`)}
function runModal(date){const e=currentEvent(date)||{title:'',distance:'',kind:'easy',details:''};editing={date};showModal(modalHeader('PLANEJAR CORRIDA',niceLong(date))+`<label class="fieldlabel">Nome do treino</label><input style="width:100%" id="runTitle" maxlength="160" value="${attr(e.title)}" placeholder="Ex.: 7 km progressivo"><div class="formgrid"><div><label class="fieldlabel">Distância planejada (km)</label><input id="runDistance" type="number" step="0.1" min="0" value="${attr(e.distance)}"></div><div><label class="fieldlabel">Tipo</label><select id="runKind">${[['easy','Leve'],['quality','Intervalado / ritmo'],['long','Longão'],['race','Prova']].map(([v,n])=>`<option value="${v}" ${v===e.kind?'selected':''}>${n}</option>`).join('')}</select></div></div><label class="fieldlabel">Detalhes / ritmo (opcional)</label><textarea id="runDetails" placeholder="Ex.: 6 × 400 m, 2 min recuperação...">${h(e.details||'')}</textarea><div class="sheetfooter"><button class="btn block" data-action="save-run-event" data-date="${date}">Salvar corrida</button>${state.events[date]?`<button class="btn red block" style="margin-top:9px" data-action="delete-run-event" data-date="${date}">Excluir evento planejado</button>`:''}</div>`)}
function measureModal(){showModal(modalHeader('MEDIDAS CORPORAIS','Novo registro')+`<label class="fieldlabel">Data</label><input id="measureDate" style="width:100%" type="date" value="${today()}"><div class="formgrid">${[['weight','Peso (kg)'],['waist','Cintura (cm)'],['chest','Peito (cm)'],['arm','Braço (cm)'],['thigh','Coxa (cm)'],['hip','Quadril (cm)']].map(([id,label])=>`<div><label class="fieldlabel">${label}</label><input id="measure-${id}" type="number" step="0.1" min="0" style="width:100%" placeholder="—"></div>`).join('')}</div><div class="sheetfooter"><button class="btn block" data-action="save-measure">Salvar medidas</button></div>`)}
function adjustSet(exId,i,field,delta){const type=typeFor(),p=plan(type);if(p.kind!=='gym')return;const s=getSession(true),ex=exFor(type,s).find(e=>e.id===exId);if(!ex)return;const sets=getSets(s,ex,true),v=sets[i];const next=Math.max(0,Math.round((num(v[field])+Number(delta))*100)/100);v[field]=String(next);s.updatedAt=new Date().toISOString();save();renderTrainingOnly();}
function renderTrainingOnly(){if(tab==='training'){document.getElementById('app').innerHTML=renderTraining();updateTimerDock()}else render()}
function markSet(exId,i){const type=typeFor();const s=getSession(true),ex=exFor(type,s).find(e=>e.id===exId);if(!ex)return;const sets=getSets(s,ex,true),v=sets[i];if(!v.done&&(v.kg===''||v.reps===''||num(v.reps)<=0)){toast('Preencha peso e repetições para concluir');return}v.done=!v.done;s.updatedAt=new Date().toISOString();save();const cnt=sessionCounts(s,type);if(v.done&&state.settings.timer&&sets.some((item,idx)=>idx>i&&!item.done)){const suggested=autoRest(ex,sets,i);startTimer(suggested.seconds,ex.name+' · '+suggested.reason)}else if(v.done&&state.timer?.label?.startsWith(ex.name+' · ')){state.timer=null;save()}renderTrainingOnly();if(cnt.done===cnt.total&&v.done)toast('Todas as séries concluídas! ✓')}
function copyPrev(exId){const type=typeFor(),s=getSession(true),ex=exFor(type,s).find(e=>e.id===exId),p=prev(type,exId,selected);if(!p||!ex)return;const sets=getSets(s,ex,true),source=p.exercises[exId];for(let i=0;i<sets.length;i++)if(source?.[i]){sets[i].kg=source[i].kg;sets[i].reps=source[i].reps;sets[i].done=false}save();renderTrainingOnly();toast('Carga e repetições anteriores copiadas')}
function startTimer(seconds,label='Descanso'){state.timer={end:Date.now()+Math.max(1,seconds)*1000,remain:Math.max(1,seconds),running:true,label,alerted:false};save();updateTimerDock()}
function secondsRemaining(){if(!state.timer)return 0;return Math.max(0,Math.ceil((state.timer.running?state.timer.end-Date.now():state.timer.remain*1000)/1000))}
function fmtTime(v){return `${pad(Math.floor(v/60))}:${pad(v%60)}`}
function updateTimerDock(){const el=document.getElementById('timerDock'),t=state.timer;if(!t){el.classList.add('hidden');return}const rem=secondsRemaining();if(rem===0&&t.running&&!t.alerted){t.alerted=true;t.running=false;t.remain=0;save();if(state.settings.sound)beep();toast('Descanso concluído ✓')}
 el.classList.remove('hidden');el.innerHTML=`<div class="flex1"><small>${rem===0?'Descanso concluído':h(t.label)}</small><b>${fmtTime(rem)}</b></div><button data-action="timer-shift" data-n="-30" aria-label="Diminuir 30 segundos">−30</button><button data-action="timer-pause" aria-label="${t.running?'Pausar':'Retomar'} descanso">${icon(t.running?'pause':'play',17)}</button><button data-action="timer-shift" data-n="30" aria-label="Adicionar 30 segundos">+30</button><button data-action="timer-stop" aria-label="Encerrar descanso">${icon('x',16)}</button>`}
function beep(){try{const C=window.AudioContext||window.webkitAudioContext;if(!C)return;const c=new C(),o=c.createOscillator(),g=c.createGain();o.type='sine';o.frequency.value=740;g.gain.value=.09;o.connect(g);g.connect(c.destination);o.start();o.stop(c.currentTime+.25);o.onended=()=>c.close()}catch(_){}}
function timerShift(delta){if(!state.timer)return;const rem=Math.max(0,secondsRemaining()+delta);state.timer.remain=rem;state.timer.end=Date.now()+rem*1000;state.timer.alerted=false;save();updateTimerDock()}
function timerPause(){const t=state.timer;if(!t)return;if(t.running){t.remain=secondsRemaining();t.running=false}else{t.end=Date.now()+t.remain*1000;t.running=true;t.alerted=false}save();updateTimerDock()}
function download(name,body,mime){const blob=new Blob([body],{type:mime}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=name;document.body.appendChild(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),10000)}
function backup(){const b=clone(state);b.timer=null;download('HYBRID-backup-'+today()+'.json',JSON.stringify(b,null,2),'application/json');toast('Backup JSON criado')}
function csvEscape(v){return '"'+String(v??'').replace(/"/g,'""')+'"'}
function exportCSV(){const rows=[['Data','Tipo','Exercício','Série','Carga (kg)','Repetições','Concluída','RIR','Distância (km)','Tempo (min)','Notas']];for(const s of logs()){const p=plan(s.type);if(p.kind==='gym')for(const ex of exFor(s.type,s)){getSets(s,ex).forEach((x,i)=>{if(x.kg!==''||x.reps!==''||x.done)rows.push([s.date,p.name,ex.name,i+1,x.kg,x.reps,x.done?'Sim':'Não',s.exertion?.[ex.id]??'','','',s.notes])})}else rows.push([s.date,p.name,'', '', '', '',s.run?.done?'Sim':'Não','',s.run?.distance||'',s.run?.minutes||'',s.notes])}download('HYBRID-series-'+today()+'.csv','\ufeff'+rows.map(row=>row.map(csvEscape).join(';')).join('\r\n'),'text/csv;charset=utf-8');toast('CSV exportado')}
function importBackup(file){const reader=new FileReader();reader.onload=()=>{try{const value=normalized(JSON.parse(reader.result));if(!confirm('Restaurar backup? Isso substitui seus registros atuais nesta versão. Exporte um backup antes, se precisar.'))return;state=value;state.timer=null;save();dismiss();render();toast('Backup restaurado ✓')}catch(e){alert('Falha ao importar: '+e.message)}};reader.readAsText(file)}
function decodeICS(v){return String(v).replace(/\\n/gi,' · ').replace(/\\,/g,',').replace(/\\;/g,';').replace(/\\\\/g,'\\')}
function importICS(file){const reader=new FileReader();reader.onload=()=>{try{const raw=String(reader.result).replace(/\r\n[ \t]/g,'');const groups=raw.match(/BEGIN:VEVENT[\s\S]*?END:VEVENT/gi)||[];let found=0,updated=0;for(const group of groups){const get=(key)=>{const line=group.split(/\r?\n/).find(a=>a.toUpperCase().startsWith(key));return line?line.slice(line.indexOf(':')+1):''};const title=decodeICS(get('SUMMARY')),description=decodeICS(get('DESCRIPTION')),start=get('DTSTART');const m=start.match(/(\d{4})(\d{2})(\d{2})/);if(!m||!/corrida|running|treino|workout|\brun\b|km|long|pace|interval|easy|tempo|race|fartlek|repetition|rep[eé]ti|prova/i.test(title+' '+description))continue;const date=`${m[1]}-${m[2]}-${m[3]}`;if(!state.events[date]||state.events[date].source!=='manual'){state.events[date]={title:title||'Treino importado',distance:(title.match(/(\d+(?:[.,]\d+)?)\s*km/i)||[])[1]?.replace(',','.')||'',kind:/prova|race/i.test(title)?'race':/interval|repeti|ritmo|speed|subida|tempo/i.test(title)?'quality':/long|longo/i.test(title)?'long':'easy',details:description.slice(0,500),source:'ics'};updated++}found++}save();render();toast(`${updated} evento(s) importado(s)`);if(!found)alert('Nenhuma corrida reconhecida no arquivo .ics. Verifique se há eventos de corrida no calendário.') }catch(e){alert('Erro na importação do calendário: '+e.message)}};reader.readAsText(file)}
function dispatchClick(action,d,el){if(action==='go-tab')return setTab(d.target);if(action==='pick')return selectDate(d.date);if(action==='cal-pick')return selectCalendarDate(d.date);if(action==='go-today')return tab==='calendar'?selectCalendarDate(today()):selectDate(today());if(action==='shift-week'){selected=add(selected,num(d.n));selectedType=null;return render()}if(action==='move-month'){const x=dt(monthCursor+'-01');x.setMonth(x.getMonth()+num(d.n));monthCursor=fmt(x).slice(0,7);return render()}
 if(action==='history-pick'){selected=d.date;selectedType=d.type;return setTab('training')}
 if(action==='editor')return editor(d.type);if(action==='close-modal')return dismiss();if(action==='close-outside')return;
 if(action==='edit-ex')return editEx(d.type,d.id);if(action==='save-ex'){const type=d.type,id=d.id,p=plan(type),name=document.getElementById('exName').value.trim(),sets=num(document.getElementById('exSets').value),target=document.getElementById('exTarget').value.trim(),step=num(document.getElementById('exStep').value);if(!name||sets<1||sets>12||step<=0||!target)return alert('Preencha os campos com valores válidos.');if(id){const ex=p.exercises.find(x=>x.id===id);if(!ex)return;Object.assign(ex,{name,sets,target,step})}else p.exercises.push({id:'custom_'+Date.now(),name,sets,target,step});save();editor(type);renderTrainingOnly();toast('Exercício salvo');return}
 if(action==='move-ex'){const p=plan(d.type),i=p.exercises.findIndex(x=>x.id===d.id),j=i+num(d.n);if(i>=0&&j>=0&&j<p.exercises.length){[p.exercises[i],p.exercises[j]]=[p.exercises[j],p.exercises[i]];save();editor(d.type)}return}
 if(action==='delete-ex'){if(!confirm('Excluir exercício da ficha para treinos futuros? O histórico já registrado será mantido.'))return;const p=plan(d.type);p.exercises=p.exercises.filter(x=>x.id!==d.id);save();editor(d.type);renderTrainingOnly();return}
 if(action==='save-plan'){const p=plan(d.type),name=document.getElementById('planName').value.trim();if(!name)return toast('Informe o nome da ficha');p.name=name;p.focus=document.getElementById('planFocus').value.trim();save();editor(d.type);renderTrainingOnly();toast('Ficha atualizada');return}
 if(action==='adjust')return adjustSet(d.id,num(d.i),d.field,num(d.delta));if(action==='toggle-set')return markSet(d.id,num(d.i));if(action==='copy-previous')return copyPrev(d.id);
 if(action==='finish'){const s=getSession(true);s.finishedAt=new Date().toISOString();save();renderTrainingOnly();toast('Sessão finalizada ✓');return}
 if(action==='complete-run'){const s=getSession(true);if(!s.run)s.run={};if(!s.run.done&&(!s.run.distance||num(s.run.distance)<=0)){toast('Informe a distância realizada');return}s.run.done=!s.run.done;save();renderTrainingOnly();toast(s.run.done?'Corrida registrada ✓':'Corrida desmarcada');return}
 if(action==='run-edit')return runModal(d.date||selected);if(action==='save-run-event'){const title=document.getElementById('runTitle').value.trim(),distance=document.getElementById('runDistance').value;if(!title)return toast('Informe o nome do treino');state.events[d.date]={title,distance,kind:document.getElementById('runKind').value,details:document.getElementById('runDetails').value.trim(),source:'manual'};save();dismiss();render();toast('Corrida planejada salva');return}
 if(action==='delete-run-event'){if(!confirm('Excluir apenas o evento planejado? O histórico de corridas realizadas será mantido.'))return;delete state.events[d.date];save();dismiss();render();return}
 if(action==='add-measure')return measureModal();if(action==='save-measure'){const date=document.getElementById('measureDate').value;if(!date)return toast('Informe a data');const values={date};for(const f of ['weight','waist','chest','arm','thigh','hip'])values[f]=document.getElementById('measure-'+f).value;if(Object.keys(values).every(k=>k==='date'||values[k]===''))return toast('Informe pelo menos uma medida');state.measures=state.measures.filter(x=>x.date!==date);state.measures.push(values);save();dismiss();render();toast('Medidas registradas');return}
 if(action==='delete-measure'){if(!confirm('Excluir este registro de medidas?'))return;state.measures=state.measures.filter(m=>m.date!==d.date);save();render();return}
 if(action==='timer-shift')return timerShift(num(d.n));if(action==='timer-pause')return timerPause();if(action==='timer-stop'){state.timer=null;save();return updateTimerDock()}
 if(action==='export-json')return backup();if(action==='export-csv')return exportCSV();if(action==='import-json')return document.getElementById('backupInput').click();if(action==='import-ics')return document.getElementById('icsInput').click();
 if(action==='reload-app'){toast('Atualizando arquivos...');navigator.serviceWorker?.getRegistration().then(reg=>reg?.update()).finally(()=>setTimeout(()=>location.reload(),600));return}
 if(action==='clear'){if(!confirm('Apagar TODOS os registros desta versão no aparelho? Faça um backup JSON primeiro.'))return;if(!confirm('Última confirmação: deseja apagar todos os treinos, medidas e alterações locais?'))return;state=blank();save();render();toast('Dados desta versão apagados');return}
}
function handleInput(t){const d=t.dataset;if(d.action==='chart-select'){chartExercise=t.value;return render()}
 if(d.action==='switch-type'){const choice=t.value;if(choice===baselineType(selected))delete state.overrides[selected];else state.overrides[selected]=choice;selectedType=null;save();return render()}
 if(d.input==='weekly'){const day=Number(d.day);if(!Number.isInteger(day)||day<0||day>6)return;state.settings.weeklyTypes[day]=t.value;save();render();return}
 if(d.input==='setting'){state.settings[d.field]=t.type==='checkbox'?t.checked:d.field==='defaultIncrement'?num(t.value):t.value;save();return}
 if(d.input==='notes'){const s=getSession(true);s.notes=t.value;save();return}
 if(d.input==='run'){const s=getSession(true);s.run[d.field]=t.value;save();return}
 if(d.input==='rir'){const s=getSession(true);if(!s.exertion)s.exertion={};s.exertion[d.id]=t.value;save();return}
 if(d.input==='set'){const s=getSession(true),ex=exFor(typeFor(),s).find(x=>x.id===d.id);if(!ex)return;const v=getSets(s,ex,true)[num(d.i)];v[d.field]=t.value;save()}
}
document.addEventListener('click',e=>{const el=e.target.closest('[data-action],[data-tab]');if(!el)return;if(el.dataset.action==='close-outside' && e.target===el){dismiss();return}if(el.dataset.tab){setTab(el.dataset.tab);return}dispatchClick(el.dataset.action,el.dataset,el)});
document.addEventListener('input',e=>{const el=e.target;if(el.matches('[data-input]'))handleInput(el)});
document.addEventListener('change',e=>{const el=e.target;if(el.matches('select[data-action]'))handleInput(el);else if(el.matches('[data-input]'))handleInput(el)});
document.getElementById('backupInput').addEventListener('change',e=>{const file=e.target.files?.[0];e.target.value='';if(file)importBackup(file)});
document.getElementById('icsInput').addEventListener('change',e=>{const file=e.target.files?.[0];e.target.value='';if(file)importICS(file)});
document.querySelectorAll('[data-symbol]').forEach(el=>{el.innerHTML=icon(el.dataset.symbol,23)});
init();render();setInterval(updateTimerDock,1000);
if('serviceWorker' in navigator&&(location.protocol==='https:'||location.hostname==='localhost'||location.hostname==='127.0.0.1'))window.addEventListener('load',()=>navigator.serviceWorker.register('./sw.js',{scope:'./'}).catch(e=>console.warn('Service worker:',e)));
